package com.mine.geometry_node.core.network.packet.asset.preview;
import com.mine.geometry_node.core.engine.system.asset.preview.*; import com.mine.geometry_node.core.network.packet.asset.preview.AssetPreviewPacketCodecs; import net.minecraft.network.RegistryFriendlyByteBuf; import net.minecraft.network.codec.StreamCodec; import net.minecraft.network.protocol.common.custom.CustomPacketPayload; import net.minecraft.resources.Identifier; import java.util.*;
public record PacketAssetPreviewResult(UUID requestId,AssetPreviewResultCode code,String detail) implements CustomPacketPayload {
 public static final Type<PacketAssetPreviewResult> TYPE=new Type<>(Identifier.fromNamespaceAndPath("geometry_node","asset_preview_result")); public static final StreamCodec<RegistryFriendlyByteBuf,PacketAssetPreviewResult> STREAM_CODEC=StreamCodec.of((b,p)->{b.writeUUID(p.requestId);b.writeVarInt(p.code.ordinal());b.writeUtf(p.detail,AssetPreviewLimits.PACKET_DETAIL_MAX_LENGTH);},b->new PacketAssetPreviewResult(b.readUUID(),AssetPreviewPacketCodecs.readEnum(b,AssetPreviewResultCode.values()),b.readUtf(AssetPreviewLimits.PACKET_DETAIL_MAX_LENGTH)));
 public PacketAssetPreviewResult{requestId=Objects.requireNonNull(requestId);code=Objects.requireNonNull(code);detail=Objects.requireNonNullElse(detail,"");}@Override public Type<? extends CustomPacketPayload> type(){return TYPE;}
}
